add_action( 'woocommerce_before_shop_loop_item_title', 'perfectpixel_new_product_badge', 3 );

function perfectpixel_new_product_badge() {
	global $product;
	if ( ! $product || ! $product->get_date_created() ) {
		return;
	}
	$age = time() - $product->get_date_created()->getTimestamp();
	if ( $age > max( 1, (int) '{{new_badge_days}}' ) * DAY_IN_SECONDS ) {
		return;
	}
	$color = sanitize_hex_color( '{{new_badge_color}}' );
	printf(
		'<span class="perfectpixel-new-badge" style="position:absolute;top:.5em;right:.5em;z-index:9;padding:.2em .6em;border-radius:3px;color:#fff;font-size:.8em;font-weight:600;background:%s">%s</span>',
		esc_attr( $color ? $color : '#00a32a' ),
		esc_html( '{{new_badge_text}}' )
	);
}
